# NOTE: ROLE_SERVICE_MAP is populated after SALARY_MASTER is fully loaded.
# See the end of this file for the actual population.

def validate_data_integrity() -> bool:
    """
    Validates the integrity of the RATE_CARD and TYPICAL_TEAMS data.

    This function checks for two main conditions:
    1.  That all roles defined in TYPICAL_TEAMS exist as keys in the RATE_CARD.
    2.  That there are no duplicate role names defined in the RATE_CARD.

    Returns:
        bool: True if data integrity is confirmed, False otherwise.
    """
    logger.info("Starting data integrity validation...")
    rate_card_roles: Set[str] = set(RATE_CARD.keys())
    all_roles_valid = True

    # 1. Check for duplicate roles in RATE_CARD (should be impossible with dict keys, but good practice)
    if len(rate_card_roles) != len(RATE_CARD):
        logger.error("Duplicate role definitions found in RATE_CARD.")
        # This part of the check is mostly theoretical as dict keys must be unique.
        all_roles_valid = False

    # 2. Check if all roles in TYPICAL_TEAMS exist in RATE_CARD
    for team, members in TYPICAL_TEAMS.items():
        for member in members:
            role_name = member.get("role")
            if not role_name:
                logger.error(f"'role' key missing in a member of team '{team}'. Member data: {member}")
                all_roles_valid = False
                continue

            if role_name not in rate_card_roles:
                logger.error(f"Role '{role_name}' from team '{team}' not found in RATE_CARD.")
                all_roles_valid = False

    if all_roles_valid:
        logger.info("Data integrity validation successful. All roles in TYPICAL_TEAMS are defined in RATE_CARD.")
    else:
        logger.error("Data integrity validation failed. Please check the logs for details.")

    return all_roles_valid

if __name__ == '__main__':
    # This block allows the script to be run directly for validation purposes.
    logger.info("Running rate_card.py as a standalone script for validation.")
    validation_passed = validate_data_integrity()
    if validation_passed:
        print("\nValidation Successful: All team roles are correctly defined in the rate card.")
    else:
        print("\nValidation Failed: Inconsistencies found. Please review the error logs above.")
