EDUCATION_TIERS = ["SMK", "D3", "S1", "S2", "S3"]

EDUCATION_EXP_KEY = {
    "SMK": "exp_smk", "D3": "exp_d3", "S1": "exp_s1",
    "S2": "exp_s2", "S3": "exp_s3",
}

# ==============================================================================
# SALARY MASTER HELPER FUNCTIONS
# ==============================================================================

def get_salary_rate(role: str, level: int, field: str = "external_margin30") -> float:
    """
    Get a specific salary rate for a role at a given level from SALARY_MASTER.

    Args:
        role: The job title/role (must exist in SALARY_MASTER).
        level: The seniority level (1-24).
        field: The cost field to retrieve. Options:
            - "gaji_pokok": Base salary
            - "man_month": Gross man-month cost (internal)
            - "man_day": Man-day rate
            - "external_margin30": External client price with 30% margin (default)

    Returns:
        The requested rate as a float, or 0 if not found.
    """
    try:
        return SALARY_MASTER[role]["levels"][level].get(field, 0)
    except (KeyError, TypeError):
        logger.warning(f"Salary rate not found for role='{role}', level={level}, field='{field}'")
        return 0


def find_level_by_experience(role: str, education: str, years_experience: float) -> int:
    """
    Find the appropriate level for a role based on education tier and years of experience.

    This function implements the flexible competency-based pricing model:
    - Higher education = fewer years of experience required for the same level
    - S3 (Doctoral) reaches senior levels faster than SMK (Vocational)
    - Returns the highest level where the experience requirement is met

    Args:
        role: The job title/role (must exist in SALARY_MASTER).
        education: Education tier ("SMK", "D3", "S1", "S2", or "S3").
        years_experience: Total years of relevant professional experience.

    Returns:
        The matched level (1-24), or 1 if no match found.

    Example:
        >>> find_level_by_experience("Data Scientist", "S1", 5)
        10  # S1 with 5 years → Level 10
        >>> find_level_by_experience("Data Scientist", "S2", 3)
        10  # S2 with 3 years → same Level 10 (higher edu, fewer years needed)
    """
    if role not in SALARY_MASTER:
        logger.warning(f"Role '{role}' not found in SALARY_MASTER")
        return 1

    exp_key = EDUCATION_EXP_KEY.get(education.upper())
    if not exp_key:
        logger.warning(f"Invalid education tier '{education}'. Use: {EDUCATION_TIERS}")
        return 1

    best_level = 1
    for lvl, data in SALARY_MASTER[role]["levels"].items():
        required_exp = data.get(exp_key)
        if required_exp is not None and years_experience >= required_exp:
            if lvl > best_level:
                best_level = lvl

    return best_level


def get_flexible_personnel_cost(
    role: str,
    education: str,
    years_experience: float,
    months: int = 1,
    field: str = "external_margin30"
) -> Dict[str, Any]:
    """
    Calculate flexible personnel cost based on competency (role + education + experience).

    This replaces the old fixed-rate model (Rp 20M/person/month) with a dynamic
    lookup that considers individual competency factors.

    Args:
        role: The job title/role.
        education: Education tier ("SMK", "D3", "S1", "S2", or "S3").
        years_experience: Total years of relevant professional experience.
        months: Duration in months (default 1).
        field: Cost field to use for calculation (default "external_margin30").

    Returns:
        A dictionary with the full cost breakdown including:
        - role, education, years_experience, matched_level
        - monthly_rate, total_cost, man_day_rate
        - experience_requirements for the matched level
    """
    level = find_level_by_experience(role, education, years_experience)
    monthly_rate = get_salary_rate(role, level, field)
    man_day = get_salary_rate(role, level, "man_day")
    gaji_pokok = get_salary_rate(role, level, "gaji_pokok")

    level_data = SALARY_MASTER.get(role, {}).get("levels", {}).get(level, {})

    return {
        "role": role,
        "education": education.upper(),
        "years_experience": years_experience,
        "matched_level": level,
        "group": SALARY_MASTER.get(role, {}).get("group", "Unknown"),
        "category": SALARY_MASTER.get(role, {}).get("category", "Unknown"),
        "gaji_pokok": gaji_pokok,
        "monthly_rate": monthly_rate,
        "man_day_rate": man_day,
        "months": months,
        "total_cost": monthly_rate * months,
        "experience_requirements": {
            "SMK": level_data.get("exp_smk"),
            "D3": level_data.get("exp_d3"),
            "S1": level_data.get("exp_s1"),
            "S2": level_data.get("exp_s2"),
            "S3": level_data.get("exp_s3"),
        },
    }


def calculate_team_cost_flexible(
    team_members: List[Dict[str, Any]],
    months: int = 1,
    field: str = "external_margin30"
) -> Dict[str, Any]:
    """
    Calculate total team cost using the flexible competency-based model.

    This is the replacement for the old headcount × flat_rate model.
    Each team member is priced individually based on their competency.

    Args:
        team_members: List of dicts, each with keys:
            - "role": str (job title)
            - "education": str (SMK/D3/S1/S2/S3)
            - "years_experience": float
        months: Project duration in months.
        field: Cost field to use (default "external_margin30").

    Returns:
        A dictionary with per-member breakdowns and total team cost.

    Example:
        >>> team = [
        ...     {"role": "Data Governance Lead", "education": "S2", "years_experience": 8},
        ...     {"role": "Data Analyst", "education": "S1", "years_experience": 3},
        ...     {"role": "Data Engineer", "education": "S1", "years_experience": 5},
        ... ]
        >>> result = calculate_team_cost_flexible(team, months=6)
    """
    breakdowns = []
    total = 0

    for member in team_members:
        cost = get_flexible_personnel_cost(
            role=member.get("role", ""),
            education=member.get("education", "S1"),
            years_experience=member.get("years_experience", 0),
            months=months,
            field=field,
        )
        breakdowns.append(cost)
        total += cost["total_cost"]

    return {
        "team_size": len(team_members),
        "months": months,
        "pricing_field": field,
        "member_breakdowns": breakdowns,
        "total_personnel_cost": total,
        "average_monthly_rate": total / (len(team_members) * months) if team_members and months > 0 else 0,
    }


def list_salary_master_roles() -> List[str]:
    """Return a sorted list of all roles available in SALARY_MASTER."""
    return sorted(SALARY_MASTER.keys())


def get_role_salary_range(role: str, field: str = "external_margin30") -> Dict[str, Any]:
    """
    Get the salary range (min/max) for a role across all levels.

    Args:
        role: The job title/role.
        field: The cost field to check.

    Returns:
        Dict with min_level, max_level, min_rate, max_rate.
    """
    if role not in SALARY_MASTER:
        return {"error": f"Role '{role}' not found in SALARY_MASTER"}

    levels = SALARY_MASTER[role]["levels"]
    rates = [(lvl, data.get(field, 0)) for lvl, data in levels.items()]
    rates.sort(key=lambda x: x[1])

    return {
        "role": role,
        "field": field,
        "min_level": rates[0][0],
        "min_rate": rates[0][1],
        "max_level": rates[-1][0],
        "max_rate": rates[-1][1],
        "level_count": len(rates),
    }

