# Merge SALARY_MASTER_EXTENSION into SALARY_MASTER
SALARY_MASTER.update(SALARY_MASTER_EXTENSION)


def get_all_roles():
    """Return sorted list of all roles available in SALARY_MASTER."""
    return sorted(SALARY_MASTER.keys())


def get_roles_by_category(category_name):
    """Return roles filtered by salary category (Management/Managerial/Lead/Analyst/Engineer/Officer)."""
    return sorted([
        role for role, data in SALARY_MASTER.items()
        if data.get("category", "").lower() == category_name.lower()
    ])


def get_roles_by_tier(tier_name):
    """Return roles filtered by salary tier. DEPRECATED: Use get_roles_by_category() instead."""
    # Backward compatibility: map old tier names to new category names
    tier_map = {"Board": "Management", "Manager": "Managerial"}
    category = tier_map.get(tier_name, tier_name)
    return get_roles_by_category(category)


def get_role_summary(role_name):
    """Return a summary dict for a role including tier, group, and rate range."""
    if role_name not in SALARY_MASTER:
        return {"error": f"Role '{role_name}' not found in SALARY_MASTER"}
    data = SALARY_MASTER[role_name]
    levels = data.get('levels', {})
    rates = [v.get('man_month', 0) for v in levels.values()]
    return {
        "role": role_name,
        "group": data.get("group", "N/A"),
        "category": data.get("category", "N/A"),
        "num_levels": len(levels),
        "min_rate": min(rates) if rates else 0,
        "max_rate": max(rates) if rates else 0,
    }

